using UnityEngine;

public interface IPlayerState
{
    void Enter();
    void Tick(float dt);
    void Exit();
}

public sealed class PlayerStateMachine : MonoBehaviour
{
    private IPlayerState _current;

    public void SetState(IPlayerState next)
    {
        if (_current == next) return;
        _current?.Exit();
        _current = next;
        _current?.Enter();
    }

    private void Update()
    {
        _current?.Tick(Time.deltaTime);
    }
}

using UnityEngine;

public interface IWeaponForm
{
    string Id { get; }
    void OnEquip();
    void OnUnequip();
    void Primary();
    void Secondary();
}

public sealed class HornWeaponController : MonoBehaviour
{
    [SerializeField] private MonoBehaviour[] forms; // assign components that implement IWeaponForm

    private IWeaponForm _active;

    public void Equip(string id)
    {
        var next = FindForm(id);
        if (next == null || next == _active) return;

        _active?.OnUnequip();
        _active = next;
        _active.OnEquip();
    }

    public void Primary() => _active?.Primary();
    public void Secondary() => _active?.Secondary();

    private IWeaponForm FindForm(string id)
    {
        foreach (var mb in forms)
        {
            if (mb is IWeaponForm f && f.Id == id)
                return f;
        }
        return null;
    }
}

using System.Collections;
using UnityEngine;

public sealed class WaveDirector : MonoBehaviour
{
    [SerializeField] private Transform[] spawnPoints;
    [SerializeField] private GameObject enemyPrefab;

    [Header("Pacing")]
    [SerializeField] private int maxAlive = 8;
    [SerializeField] private float spawnInterval = 1.0f;
    [SerializeField] private int enemiesPerWave = 20;

    private int _alive;

    public IEnumerator RunWave()
    {
        int spawned = 0;

        while (spawned < enemiesPerWave)
        {
            if (_alive < maxAlive)
            {
                SpawnEnemy();
                spawned++;
            }
            yield return new WaitForSeconds(spawnInterval);
        }

        // wait until wave is cleared
        while (_alive > 0)
            yield return null;
    }

    private void SpawnEnemy()
    {
        var p = spawnPoints[Random.Range(0, spawnPoints.Length)];
        var go = Instantiate(enemyPrefab, p.position, p.rotation);
        _alive++;

        // Example: enemy reports death back to director
        var reporter = go.AddComponent<DeathReporter>();
        reporter.OnDead += () => _alive--;
    }

    private sealed class DeathReporter : MonoBehaviour
    {
        public System.Action OnDead;
        // Call OnDead?.Invoke() from your enemy death logic.
        private void OnDestroy() => OnDead?.Invoke();
    }
}
